        <script>document.getElementById('copy-link').addEventListener('click',function(){var button=this,shareUrl=<?=json_encode($shareUrl,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;function copied(){button.textContent='Link copied';window.setTimeout(function(){button.textContent='Copy link'},1800)}function fallbackCopy(){var field=document.createElement('textarea');field.value=shareUrl;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();var success=document.execCommand('copy');document.body.removeChild(field);if(success){copied()}else{window.prompt('Copy this story link:',shareUrl)}}if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(shareUrl).then(copied).catch(fallbackCopy)}else{fallbackCopy()}});</script></body></html>